head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setNoResultMessage]<br/>GridView 컴포넌트의 noResultMessage 속성을 설정합니다.",
    "validation" : [
        "noResultMessageVisible=true 이고, noResultMessageStyle 속성을 맞게 설정한 경우 동작합니다.",
        "데이터가 모두 제거되었거나 필터에 의해 GridView 에 표시할 데이터가 없을때 동작합니다.",
        "setNoResultMessage 로 설정한 메시지가 Body 영역에 보여져야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        noResultMessageVisible: true,
        useNoResultMessageURL: false,
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:350px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



scwin.btn_setNoResultMessage_onclick = function () {
    let message = par_message.getText();
    target1.setNoResultMessage(message);
    wf_body_bottom.getObj("scwin").setReturnValue("setNoResultMessage('" + message + "') 실행 완료");
}



scwin.btn_removeAll_onclick = function () {
    dlt_bind.removeAll();

    scwin.btn_noResultMessage_onclick();
}



scwin.btn_setColumnFilter_onclick = function () {
    dlt_bind.setColumnFilter({type:'row', colIndex:'col1', key:"test", condition:'and'});

    scwin.btn_noResultMessage_onclick();
}



scwin.btn_noResultMessage_onclick = function () {
    let targetElement = document.querySelector('div[id*="target1_noresult"]');

    if (targetElement) {
        let textContent = targetElement.textContent;
        wf_body_bottom.getObj("scwin").setReturnValue("noResultMessage : " + textContent);
    }
}
